    """Resolve reader-local object references into a stable semantic graph."""
    from pypdf.generic import IndirectObject, StreamObject, BooleanObject, NullObject
    page_refs = {}
    page_objects = {}
    for index, page in enumerate(document.pages):
        reference = page.indirect_reference
        if reference is not None:
            page_refs[(reference.idnum, reference.generation)] = index
        page_objects[id(page)] = index

    def canonical(value, stack=()):
        if isinstance(value, IndirectObject):
            page_index = page_refs.get((value.idnum, value.generation))
            if page_index is not None:
                return ("page", page_index)
            return canonical(value.get_object(), stack)
        if id(value) in page_objects:
            return ("page", page_objects[id(value)])
        if isinstance(value, (dict, list, tuple)):
            identity = id(value)
            if identity in stack:
                return ("cycle", stack.index(identity))
            stack = stack + (identity,)
            if isinstance(value, dict):
                excluded = {"/Length", "/Filter", "/DecodeParms"} if isinstance(value, StreamObject) else set()
                entries = tuple((str(key), canonical(value[key], stack)) for key in sorted(value, key=str) if str(key) not in excluded)
                if isinstance(value, StreamObject):
                    return ("stream", hashlib.sha256(value.get_data()).hexdigest(), entries)
                return ("dictionary", entries)
            return ("array", tuple(canonical(item, stack) for item in value))
        if value is None or isinstance(value, NullObject):
            return None
        if isinstance(value, BooleanObject):
            return ("boolean", value.value)
        if isinstance(value, bytes):
            return ("bytes", value.hex())
        if isinstance(value, str):
            return ("string", str(value))
        if isinstance(value, (int, float)):
            return ("number", float(value))
